let prefabFilter='all';
function renderCatalogue(){
 const intro=$('#intro');intro.replaceChildren(el('p',t('PREFAB RESEARCH LIBRARY','预制建筑研究资料库'),'eyebrow'),el('h1',t('Explore what’s already being built.','看看已有的建筑方案。')),el('p',t('Use Australian designs as a starting point for understanding layouts, construction methods and your own requirements.','参考澳大利亚的设计，了解空间布局、建造方法及你自己的项目需求。'),'intro-copy'));
 const figure=el('figure',undefined,'catalogue-feature'),photo=el('img');photo.src='assets/prefab/prebuilt-habitat.jpg';photo.alt=t('Prebuilt home pictured in the supplier’s pre-designed homes gallery','Prebuilt 预设计住宅图库中的住宅');const caption=el('figcaption'),credit=el('a',t('Image source: Prebuilt · supplier reference','图片来源：Prebuilt · 供应商参考'));credit.href='https://www.prebuilt.com.au/pre-designed-homes/';credit.target='_blank';credit.rel='noopener noreferrer';caption.append(credit);figure.append(photo,caption);intro.append(figure,el('p',t('Choose a category, then visit the supplier for the full design. We have not evaluated suitability for your site.','选择类别，再访问供应商网站查看完整设计。我们尚未评估这些方案对你的地块是否适用。'),'notice'));
 document.title=t('Fabrication Intelligence — Prefab references','Fabrication Intelligence — 预制建筑参考');
 $('#progress').hidden=true;
 const screen=$('#screen');screen.classList.add('catalogue-screen');
 screen.append(el('p',t('AUSTRALIAN SUPPLIER REFERENCES','澳大利亚供应商参考'),'eyebrow'),el('h2',t('Prefab designs & products','预制建筑设计与产品')),el('p',t('Explore 12 designs and product ranges from 9 companies. Open each original source to see its photos, floorplans and latest details.','探索 9 家公司的 12 项设计及产品系列。打开原始来源，查看照片、平面图及最新详情。'),'subheading'));
 screen.append(el('p',t('Independent research catalogue. These designs belong to their respective suppliers. Listings do not imply a partnership, resale rights, availability through us, or a cheaper overseas equivalent.','独立研究目录。设计属于各自供应商。收录不代表合作关系、转售授权、可通过我们采购，或存在更便宜的海外同等产品。'),'notice'));
 const filters=el('div',undefined,'catalogue-filters');filters.setAttribute('role','group');filters.setAttribute('aria-label',t('Filter product type','筛选产品类别'));
 const categories=[['all','All references','全部参考'],['homes','Homes','住宅'],['commercial','Commercial','商业设施'],['systems','Building systems','建筑系统']];
 for(const [id,en,zh]of categories){const b=el('button',t(en,zh),'secondary');b.type='button';b.setAttribute('aria-pressed',String(prefabFilter===id));b.onclick=()=>{prefabFilter=id;render();};filters.append(b);}screen.append(filters);
 const matches=prefabProducts.filter(p=>prefabFilter==='all'||p.category===prefabFilter),count=el('p',t(`${matches.length} references · Sources reviewed 14 September 2026`,`${matches.length} 项参考 · 来源核查于 2026 年 9 月 14 日`),'saved-note');count.setAttribute('role','status');screen.append(count);
 const grid=el('div',undefined,'catalogue-grid');for(const p of matches){const card=el('article',undefined,'prefab-card');card.append(el('p',p.company,'supplier'),el('h3',lang==='zh'&&p.zhName?p.zhName:p.name),el('p',t(...p.spec),'product-spec'),el('p',t(...p.summary),'product-summary'));const link=el('a',t('View original design & details ↗','查看原始设计与详情 ↗'),'source-link');link.href=p.url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',t(`View ${p.company} ${p.name} on supplier website (new tab)`,`在供应商网站查看 ${p.company} ${p.zhName||p.name}（新标签页）`));card.append(link);grid.append(card);}screen.append(grid,el('p',t('Supplier links open external websites. This catalogue and your staircase request stay local. The Stage 1 request currently covers staircases only.','供应商链接会打开外部网站。本目录与楼梯需求保持本地运行。第一阶段需求表目前仅适用于楼梯。'),'saved-note'));
}
// A linkable local catalogue view; switching within the app preserves the form in memory.
if(new URLSearchParams(location.search).get('view')==='catalogue'){view='catalogue';render();}
